import json
from datetime import datetime, timezone
from decimal import Decimal

record = {
    "event": "order_created",
    "amount": Decimal("19.99"),
    "created_at": datetime(2026, 7, 1, 12, 30, tzinfo=timezone.utc),
    "items": [1, 2, 3],
}


class DEJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, datetime):
            return {"__type__": "datetime", "value": obj.isoformat()}
        if isinstance(obj, Decimal):
            return {"__type__": "decimal", "value": str(obj)}
        return super().default(obj)


def de_object_hook(d):
    t = d.get("__type__")
    if t == "datetime":
        return datetime.fromisoformat(d["value"])
    if t == "decimal":
        return Decimal(d["value"])
    return d


# stdlib round-trip preserving exact types
text = json.dumps(record, cls=DEJSONEncoder)
restored = json.loads(text, object_hook=de_object_hook)
assert restored["amount"] == Decimal("19.99")
assert restored["created_at"] == record["created_at"]
print("stdlib ok:", type(restored["amount"]).__name__, type(restored["created_at"]).__name__)

# orjson: faster, serializes datetime natively (returns bytes)
import orjson

fast_bytes = orjson.dumps({"created_at": record["created_at"], "items": record["items"]})
print("orjson:", fast_bytes)
print("orjson back:", orjson.loads(fast_bytes))

